sql_query:
SELECT "PubMed ID"
FROM clinical_trials
WHERE "Cancer type" = 'Head and Neck' AND "Name of ICI" = 'Nivolumab' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "PubMed ID" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Head and Neck' AND "Name of ICI" = 'Nivolumab' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_pubmed_url(source_value) AS "pubmed_url"
FROM base;
